    17	std::string percent_encoded(const std::string& text)
    18	{
    19	    std::string encoded;
    20	    for (const unsigned char c : text) {
    21	        if (std::isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
    22	            encoded += static_cast<char>(c);
    23	        } else {
    24	            char escaped[4];
    25	            std::snprintf(escaped, sizeof(escaped), "%%%02X", c);
