   102	        return false;
   103	    std::string verifier, challenge, state;
   104	    m_deps.pkce(verifier, challenge, state);
   105	    CloudAuthorization authorization;
   106	    authorization.client_id     = kCloudClientId;
   107	    authorization.port          = kCloudCallbackPort;
   108	    authorization.redirect_uri  = "http://127.0.0.1:" + std::to_string(kCloudCallbackPort) + "/callback";
   109	    authorization.scope         = "read write";
   110	    authorization.state         = state;
   111	    authorization.code_verifier = verifier;
   112	    authorization.token_url     = m_server + "/o/token/";
   113	    authorization.success_url   = m_server + "/ent/jusprin/v2/signed_in/";
   114	    authorization.failure_url   = m_server + "/ent/jusprin/v2/sign_in_failed/";
   115	    authorization.authorize_url = m_server + "/o/authorize/?" +
   116	                                  query({{"response_type", "code"},
   117	                                         {"client_id", authorization.client_id},
   118	                                         {"redirect_uri", authorization.redirect_uri},
   119	                                         {"scope", authorization.scope},
   120	                                         {"state", state},
   121	                                         {"code_challenge", challenge},
   122	                                         {"code_challenge_method", "S256"}});
   123	
   124	    const std::uint64_t generation = ++m_generation;
   125	    std::weak_ptr<Inbox> inbox     = m_inbox;
   126	    if (!m_deps.authorize(authorization, [inbox, generation](CloudAuthorizationResult result) {
   127	            if (const auto target = inbox.lock())
   128	                target->push({generation, Inbox::Kind::Authorized, std::move(result), {}});
   129	        }))
   130	        return false;
   131	    m_authorization = std::move(authorization);
   132	    m_phase         = CloudSignInPhase::Browser;
   133	    return true;
