def inline_link(s):
    return f'<span style="color:var(--action-primary);font-weight:700">{escape(s)}</span>'

def field(value, placeholder=False):
    """.onboarding-field: as tall as a primary button, the field's radius and padding, on surface-raised."""
    ink = '--text-tertiary' if placeholder else '--text-primary'
    return (f'<div data-c="Field" class="body" style="{BOX}flex:1 1 0;min-width:0;height:var(--component-buttonPrimary-height);display:flex;align-items:center;padding:0 var(--component-field-paddingX);'
            f'background:var(--surface-raised);border-radius:var(--component-field-radius);box-shadow:inset 0 0 0 1px var(--border-subtle);color:var({ink});white-space:nowrap;overflow:hidden">{escape(value)}</div>')

def or_rule():
    rule = f'<div style="{BOX}flex:1 1 0;height:1px;background:var(--border-subtle)"></div>'
    return row([rule, text('body-small', 'or', '--text-secondary', 'flex:none', True), rule], 12, name='or')

def note(s, color='--text-secondary'):
    return text('body-small', s, color)

def error(s):
    return text('label', s, '--status-danger')

def link_row(links, cancel=True):
    """.onboarding-link-row: the links with dots between them, Cancel at the far end."""
    dot = text('label-bold', '·', '--text-secondary', 'flex:none', True)
    left = row(sum(([dot, link(s)] for s in links), [])[1:], 0, 'flex:none') if links else ''
    return row([f'<div style="{BOX}margin-left:calc(-1 * var(--space-4))">{left}</div>'] + ([link('Cancel')] if cancel else []), 12, justify='space-between', name='Links')

def code_cells(digits='', active=None, refused=False):
    """CodeField: six 48 px cells, the section type; the next cell carries the focus ring, and a refused code turns every cell's line red."""
    def cell(i):
        ring = 'inset 0 0 0 1px var(--status-danger)' if refused else 'inset 0 0 0 2px var(--action-primary)' if i == active else 'inset 0 0 0 1px var(--border-subtle)'
        return (f'<div class="section" style="{BOX}width:48px;height:48px;display:flex;justify-content:center;align-items:center;background:var(--surface-raised);'
                f'border-radius:var(--radius-small);box-shadow:{ring};color:var(--text-primary)">{escape(digits[i] if i < len(digits) else "")}</div>')
    return f'<div data-n="Code" style="{BOX}display:flex;gap:var(--space-8);margin:var(--space-8) 0 var(--space-4)">' + ''.join(cell(i) for i in range(6)) + '</div>'

def google_button():
    return (f'<button type="button" data-c="Button/Secondary:State=Default" style="{BTN}{BOX}align-self:stretch;margin-top:var(--space-8);min-height:var(--component-buttonPrimary-height);display:flex;gap:6px;padding:6px var(--space-12);'
            'justify-content:center;align-items:center;background:var(--surface-raised);border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle)">'
            f'<img src="{GOOGLE_MARK}" alt="" style="{BOX}width:16px;height:16px;display:block"><span class="body-small-bold" style="white-space:nowrap;color:var(--text-primary)">Continue with Google</span></button>')

def sign_in_door(state=None, title=True):
    """state: None (at rest), 'waiting' (on the browser), 'signed-in', 'choose', 'choose-wrong-password', 'code', 'code-wrong', 'code-spent'."""
    head = lambda s: text('section', s)
    if state is None:
        tail = [google_button(), or_rule(), row([field('you@example.com', True), primary('Continue with email')], 12, name='Email'),
                note('New or existing account, same door. Google opens your browser; email stays here.'),
                rich('body-small', f'By signing in you agree to the {inline_link("Terms")} and {inline_link("Privacy Policy")}.', '--text-secondary')]
        return ([head(OFFER_HEAD), note(OFFER_DETAIL)] if title else []) + tail
    if state == 'waiting':
        return [row([icon('refresh-cw', '--text-primary', 24), head('Finish signing in in your browser.')], 8),
                note('The app continues on its own once the browser is done.'),
                rich('body-small', f'Nothing happened? {inline_link("Open the browser again")}', '--text-secondary'),
                link_row(['Use an email code instead'])]
    if state == 'signed-in':
        return [head(f'Signed in as {EMAIL} · 500 credits')]
    if state.startswith('choose'):
        wrong = state == 'choose-wrong-password'
        out = [head('How do you want to sign in?'), rich('body-small', f'{EMAIL}. {inline_link("Change email")}', '--text-secondary'),
               f'<div style="{BOX}align-self:stretch;margin-top:var(--space-8);display:flex">{primary("Email me a 6-digit code", block=True)}</div>',
