    new_base = '{}-{}'.format(plan_name, billing_cycle)
    current = getattr(getattr(user, 'subscription', None), 'plan_id', None)
    if current and current.startswith('{}-'.format(plan_name)):
        for suffix in TIER_SUFFIXES:
            if current.endswith(suffix):
                return '{}{}'.format(new_base, suffix)
        if current in ('pro-annual', 'pro-monthly'):
            return new_base
    if plan_name == 'pro':
        return '{}-v2'.format(new_base)
    return new_base

